package dev.utherhel.attributification.selftest;

import java.util.ArrayList;
import java.util.List;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;

/**
 * Small world helpers for scenes: console commands and entities found by scoreboard tag (summon them with
 * {@code Tags:["..."]}). Only calls that are the same on 1.20.1 - 1.21.x. Generated by dev/modtest/sync.py; edit the
 * template.
 */
public final class Probe {
    private Probe() {
    }

    /** Runs console commands as the server (permission level 4, output suppressed). */
    public static void cmd(MinecraftServer server, String... commands) {
        for (String c : commands) TestCompat.command(server, c);
    }

    /** Every overworld entity with scoreboard tag {@code tag}. */
    public static List<Entity> tagged(MinecraftServer server, String tag) {
        List<Entity> out = new ArrayList<>();
        for (Entity e : server.overworld().getAllEntities()) {
            if (e != null && TestCompat.tags(e).contains(tag)) out.add(e);
        }
        return out;
    }

    /** The single living overworld entity with tag {@code tag}; throws if there is none. */
    public static LivingEntity living(MinecraftServer server, String tag) {
        List<Entity> found = tagged(server, tag);
        for (Entity e : found) {
            if (e instanceof LivingEntity l && l.isAlive()) return l;
        }
        throw new IllegalStateException(found.isEmpty() ? "no entity tagged " + tag
            : "the entity tagged " + tag + " is dead or removed (" + found.get(0).getType().getDescriptionId() + ")");
    }

    /** "expected ~ actual" check helper: null when |a - b| <= eps. */
    public static String near(String what, double actual, double expected, double eps) {
        return Math.abs(actual - expected) <= eps ? null : what + " = " + actual + ", expected " + expected;
    }
}
